DROP TABLE IF EXISTS `sys_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '菜单ID',
  `parent_id` bigint DEFAULT '0' COMMENT '父菜单ID',
  `menu_name` varchar(64) NOT NULL COMMENT '菜单名称',
  `menu_type` char(1) NOT NULL COMMENT '类型: M=目录 C=菜单 F=按钮',
  `path` varchar(255) DEFAULT NULL COMMENT '路由路径',
  `component` varchar(255) DEFAULT NULL COMMENT '组件路径',
  `perms` varchar(128) DEFAULT NULL COMMENT '权限标识, 如 system:user:list',
  `icon` varchar(64) DEFAULT NULL COMMENT '图标',
  `sort_no` int DEFAULT '0' COMMENT '排序',
  `is_visible` tinyint DEFAULT '1' COMMENT '是否显示',
  `dashboard_perm` tinyint NOT NULL DEFAULT '0' COMMENT 'å·¥ä½œå° KPI éœ€ç‹¬ç«‹é‰´æƒ (0=å¦ 1=æ˜¯)',
  `status` tinyint DEFAULT '1' COMMENT '状态',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_sys_menu_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2090345792472715266 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='菜单权限表';
